Provide a minimal unified diff for `internal/api/webhook_dispatcher.go` to enforce a `10 * time.Second` timeout on `httpClient` and cap response body reads to `1 << 20` bytes (1 MiB) via `io.LimitReader`.

```go
package api

import (
	"bytes"
	"io"
	"net/http"
)

var httpClient = &http.Client{}

func PostEvent(url string, payload []byte) ([]byte, error) {
	resp, err := httpClient.Post(url, "application/json", bytes.NewReader(payload))
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	return io.ReadAll(resp.Body)
}
```

